// MajesticToolkit Document Studio 0.7.0 — validated offline documents and immutable local revisions.
export const DOCUMENT_PREFIX = 'majesticDocumentV7:';
export const DOCUMENT_LIMITS = Object.freeze({records:1800,templates:450,documents:1350,fields:40,versions:60,body:60000,backupBytes:48*1024*1024});
export const FIELD_TYPES = Object.freeze({text:'Строка',textarea:'Многострочный текст',date:'Дата',number:'Число',select:'Список'});
const timestamp = () => new Date().toISOString();
const makeId = () => globalThis.crypto?.randomUUID?.() ?? `doc-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
function object(raw,label='Запись'){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error(`${label}: ожидался объект`);return raw;}
function str(value,label,max,optional=false){if(typeof value!=='string')throw Error(`Поле «${label}» должно быть строкой`);const v=value.trim();if(v.length>max||(!optional&&!v))throw Error(`Некорректное поле «${label}» (до ${max} символов)`);return v;}
function identifier(x){const id=str(x,'ID',128);if(!/^[\w-]{8,128}$/.test(id))throw Error('Недопустимый идентификатор');return id;}
function dateTime(v){const t=str(v,'Дата изменения',40);if(!Number.isFinite(Date.parse(t)))throw Error('Некорректная дата');return t;}
function linkedId(id){return id ? identifier(id) : '';}
function checkField(raw){object(raw,'Поле формы');const key=str(raw.key,'Имя поля',40);if(!/^[a-z][a-z0-9_]{0,39}$/.test(key))throw Error(`Некорректный ключ поля: ${key}`);const type=str(raw.type,'Тип поля',12);if(!Object.hasOwn(FIELD_TYPES,type))throw Error('Неизвестный тип поля');const options=type==='select'? (Array.isArray(raw.options)?raw.options: str(raw.options??'','Варианты списка',900).split('\n')).map(v=>str(v,'Вариант списка',120)).filter(Boolean):[];
 if(type==='select'&&(options.length<2||options.length>30||new Set(options).size!==options.length))throw Error('Список должен содержать 2–30 уникальных вариантов');
 return {key,type,label:str(raw.label,'Название поля',90),required:raw.required===true,options};}
export function cleanFields(raw){if(!Array.isArray(raw)||raw.length>DOCUMENT_LIMITS.fields)throw Error('Превышен лимит полей формы');const keys=new Set();return raw.map(f=>{const c=checkField(f);if(keys.has(c.key))throw Error(`Повторяется ключ поля ${c.key}`);keys.add(c.key);return c;});}
export function cleanValues(raw,fields){object(raw,'Значения формы');const values={};const allowed=new Set(fields.map(f=>f.key));for(const key of Object.keys(raw))if(!allowed.has(key))throw Error(`Лишнее поле: ${key}`);
 for(const field of fields){const v=raw[field.key]??'';if(typeof v!=='string'||v.length>6000)throw Error(`Некорректное значение «${field.label}»`);const value=v.trim();if(field.required&&!value)throw Error(`Заполните поле «${field.label}»`);if(value&&field.type==='number'&&!/^-?\d+(?:[.,]\d+)?$/.test(value))throw Error(`Поле «${field.label}» должно быть числом`);if(value&&field.type==='date'&&!/^\d{4}-\d{2}-\d{2}$/.test(value))throw Error(`Неверная дата в «${field.label}»`);if(value&&field.type==='date'&&new Date(`${value}T00:00:00Z`).toISOString().slice(0,10)!==value)throw Error(`Несуществующая дата в «${field.label}»`);if(value&&field.type==='select'&&!field.options.includes(value))throw Error(`Неизвестный вариант «${field.label}»`);values[field.key]=value;}
 return values;}
export function substitute(body,values){const text=str(body,'Содержание',DOCUMENT_LIMITS.body);return text.replace(/\{\{([a-z][a-z0-9_]*)\}\}/g,(_,key)=>values[key]??`{{${key}}}`);}
function checkPlaceholders(body,fields){const allowed=new Set(fields.map(f=>f.key));for(const match of body.matchAll(/\{\{([a-z][a-z0-9_]*)\}\}/g))if(!allowed.has(match[1]))throw Error(`Переменная {{${match[1]}}} отсутствует в форме`);}
export function cleanSnapshot(raw){object(raw,'Версия документа');const fields=cleanFields(raw.fields);const body=str(raw.body,'Содержание',DOCUMENT_LIMITS.body);checkPlaceholders(body,fields);return {number:positiveVersion(raw.number),createdAt:dateTime(raw.createdAt),title:str(raw.title,'Название',180),body,fields,values:cleanValues(raw.values,fields),departmentId:linkedId(raw.departmentId),templateId:linkedId(raw.templateId)};}
function positiveVersion(n){if(!Number.isSafeInteger(n)||n<1||n>1000000)throw Error('Некорректный номер версии');return n;}
function cleanBase(raw){return {id:identifier(raw.id),profileId:identifier(raw.profileId),createdAt:dateTime(raw.createdAt),updatedAt:dateTime(raw.updatedAt)};}
export function cleanDocumentRecord(raw){object(raw);const base=cleanBase(raw);
 if(raw.type==='template'){const fields=cleanFields(raw.fields);const body=str(raw.body,'Шаблон',DOCUMENT_LIMITS.body);checkPlaceholders(body,fields);return {...base,type:'template',title:str(raw.title,'Название',180),category:str(raw.category??'Документы','Категория',90),departmentId:linkedId(raw.departmentId),body,fields};}
 if(raw.type==='document'){if(!Array.isArray(raw.versions)||!raw.versions.length||raw.versions.length>DOCUMENT_LIMITS.versions)throw Error('У документа должна быть история версий');const versions=raw.versions.map(cleanSnapshot);for(let i=0;i<versions.length;i++)if(versions[i].number!==i+1)throw Error('Нарушена последовательность версий');const currentVersion=positiveVersion(raw.currentVersion);if(currentVersion!==versions.length)throw Error('Текущая версия должна быть последней');return {...base,type:'document',versions,currentVersion};}
 throw Error('Неизвестный тип записи Document Studio');}
export function validateDocuments(raw,profileIds,government=[]){if(!Array.isArray(raw)||raw.length>DOCUMENT_LIMITS.records)throw Error('Слишком много записей Document Studio');const ids=new Set(),profiles=profileIds?new Set(profileIds):null;const records=raw.map(cleanDocumentRecord);
 if(records.filter(r=>r.type==='template').length>DOCUMENT_LIMITS.templates||records.filter(r=>r.type==='document').length>DOCUMENT_LIMITS.documents)throw Error('Превышен лимит документов/шаблонов');
 const departments=new Map(government.filter(r=>r.type==='department').map(r=>[r.id,r]));
 for(const r of records){if(ids.has(r.id))throw Error('Повторяющийся ID записи Document Studio');ids.add(r.id);if(profiles&&!profiles.has(r.profileId))throw Error('Документ относится к неизвестному профилю');const departmentsUsed=r.type==='template'?[r.departmentId]:r.versions.map(v=>v.departmentId);for(const id of departmentsUsed)if(id){const d=departments.get(id);if(!d||d.profileId!==r.profileId)throw Error('Ведомство отсутствует либо принадлежит другому профилю');}}
 return records;}
export function createDocumentTemplate(profileId,fields){const at=timestamp();return cleanDocumentRecord({id:makeId(),profileId,type:'template',createdAt:at,updatedAt:at,...fields});}
export function editDocumentTemplate(old,fields){const prior=cleanDocumentRecord(old);if(prior.type!=='template')throw Error('Это не шаблон');return cleanDocumentRecord({...prior,...fields,type:prior.type,id:prior.id,profileId:prior.profileId,createdAt:prior.createdAt,updatedAt:timestamp()});}
function snapshot({title,body,fields,values,departmentId='',templateId=''},number){return cleanSnapshot({number,createdAt:timestamp(),title,body,fields,values,departmentId,templateId});}
export function createDocument(profileId,data){const at=timestamp();return cleanDocumentRecord({id:makeId(),profileId,type:'document',createdAt:at,updatedAt:at,currentVersion:1,versions:[snapshot(data,1)]});}
export function saveDocumentRevision(previous,data){const doc=cleanDocumentRecord(previous);if(doc.type!=='document')throw Error('Это не документ');if(doc.versions.length>=DOCUMENT_LIMITS.versions)throw Error('Лимит версий: создайте копию документа');const revised=snapshot(data,doc.versions.length+1);return cleanDocumentRecord({...doc,updatedAt:timestamp(),currentVersion:revised.number,versions:[...doc.versions,revised]});}
export function restoreDocumentRevision(previous,number){const doc=cleanDocumentRecord(previous);const target=doc.versions.find(v=>v.number===number);if(!target)throw Error('Версия не найдена');return saveDocumentRevision(doc,target);}
export function duplicateDocument(previous){const doc=cleanDocumentRecord(previous);if(doc.type!=='document')throw Error('Это не документ');const v=doc.versions.at(-1);return createDocument(doc.profileId,{...v,title:`${v.title} (копия)`.slice(0,180)});}
export function documentText(record,version){const doc=cleanDocumentRecord(record);if(doc.type!=='document')throw Error('Это не документ');const snapshot=version?doc.versions.find(v=>v.number===version):doc.versions.at(-1);if(!snapshot)throw Error('Версия не найдена');return substitute(snapshot.body,snapshot.values);}
export function documentSummary(record){const r=cleanDocumentRecord(record);return r.type==='template'?{title:r.title,type:r.type,versions:0}:{title:r.versions.at(-1).title,type:r.type,versions:r.versions.length};}
